
CREATE TABLE "Group" ("id" TEXT NOT NULL,"name" VARCHAR(80) NOT NULL,"slug" TEXT NOT NULL,"description" VARCHAR(1000) NOT NULL,"privacy" VARCHAR(12) NOT NULL DEFAULT 'PUBLIC',"creatorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Group_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GroupMember" ("id" TEXT NOT NULL,"groupId" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" VARCHAR(12) NOT NULL DEFAULT 'MEMBER',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GroupMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Page" ("id" TEXT NOT NULL,"name" VARCHAR(80) NOT NULL,"slug" TEXT NOT NULL,"description" VARCHAR(1000) NOT NULL,"category" VARCHAR(40) NOT NULL,"creatorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Page_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PageFollower" ("id" TEXT NOT NULL,"pageId" TEXT NOT NULL,"userId" TEXT NOT NULL,"followedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PageFollower_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Poll" ("id" TEXT NOT NULL,"question" VARCHAR(300) NOT NULL,"creatorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Poll_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PollOption" ("id" TEXT NOT NULL,"pollId" TEXT NOT NULL,"text" VARCHAR(120) NOT NULL,CONSTRAINT "PollOption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PollVote" ("id" TEXT NOT NULL,"optionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PollVote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Event" ("id" TEXT NOT NULL,"title" VARCHAR(120) NOT NULL,"description" VARCHAR(2000) NOT NULL,"location" VARCHAR(200) NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"creatorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EventAttendee" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"userId" TEXT NOT NULL,"status" VARCHAR(12) NOT NULL DEFAULT 'GOING',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventAttendee_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Group_slug_key" ON "Group"("slug");
CREATE UNIQUE INDEX "GroupMember_groupId_userId_key" ON "GroupMember"("groupId","userId");
CREATE UNIQUE INDEX "Page_slug_key" ON "Page"("slug");
CREATE UNIQUE INDEX "PageFollower_pageId_userId_key" ON "PageFollower"("pageId","userId");
CREATE UNIQUE INDEX "PollVote_optionId_userId_key" ON "PollVote"("optionId","userId");
CREATE UNIQUE INDEX "EventAttendee_eventId_userId_key" ON "EventAttendee"("eventId","userId");
CREATE INDEX "Group_createdAt_idx" ON "Group"("createdAt");
CREATE INDEX "GroupMember_userId_idx" ON "GroupMember"("userId");
CREATE INDEX "Page_createdAt_idx" ON "Page"("createdAt");
CREATE INDEX "PageFollower_userId_idx" ON "PageFollower"("userId");
CREATE INDEX "Poll_createdAt_idx" ON "Poll"("createdAt");
CREATE INDEX "PollOption_pollId_idx" ON "PollOption"("pollId");
CREATE INDEX "PollVote_userId_idx" ON "PollVote"("userId");
CREATE INDEX "Event_startsAt_idx" ON "Event"("startsAt");
CREATE INDEX "Event_creatorId_idx" ON "Event"("creatorId");
CREATE INDEX "EventAttendee_userId_idx" ON "EventAttendee"("userId");
ALTER TABLE "Group" ADD CONSTRAINT "Group_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
